using UnityEditor;using UnityEngine;
[CustomEditor(typeof(CardLab))]public sealed class CardLabEditor:Editor{
 bool Section(string title,bool initial=false){string key="CardLabInspector."+title;bool open=SessionState.GetBool(key,initial);open=EditorGUILayout.Foldout(open,title,true,EditorStyles.foldoutHeader);SessionState.SetBool(key,open);return open;}
 void Field(string name,string label){var property=serializedObject.FindProperty(name);if(property!=null)EditorGUILayout.PropertyField(property,new GUIContent(label),true);}
 void Action(string label,System.Action action){using(new EditorGUI.DisabledScope(!Application.isPlaying))if(GUILayout.Button(label))action();}
 public override void OnInspectorGUI(){serializedObject.Update();var lab=(CardLab)target;
 Field("arena","场景入口");
 if(Section("环境",true)){Field("autoAttack","普通攻击");Field("invincible","玩家免伤");Field("freezeEnemies","冻结敌人");Field("autoSpawnEnemies","自动生怪");Field("spawnInterval","生成间隔");Action("重置实验",lab.ResetLab);}
 if(Section("木桩")){Field("targetHP","生命");Field("spawnTargetsOnReset","重置时生成");Field("targetCount","排列数量");Field("targetDistance","排列距离");Field("targetGap","排列间距");Field("singleTargetOffset","单桩位置");Field("layoutOffsets","自定义布局");Field("placement","鼠标操作");Action("放置单桩",lab.AddTarget);Action("生成一排",lab.SpawnTargets);Action("应用布局",lab.ApplyLayout);Action("清除木桩",lab.ClearTargets);}
 if(Section("卡牌装配")){Field("startingCards","开局预装");Field("selectedCard","选中卡牌");Field("desiredLevel","目标等级");Action("获取一次",lab.GrantSelected);Action("提升至目标等级",lab.SetSelected);Field("presets","组合预设");Field("selectedLoadout","选中组合");Action("应用组合",lab.ApplyLoadout);Action("保存组合资产",()=>SaveLoadout(lab));if(!string.IsNullOrEmpty(lab.loadoutResult))EditorGUILayout.HelpBox(lab.loadoutResult,MessageType.Info);}
 if(Section("射程与视野")){Field("showAttackRange","显示射程");Field("attackRangeColor","圆圈颜色");Field("attackRangeLineWidth","线宽");Field("minAttackRange","射程调试下限");Field("maxAttackRange","射程调试上限");Field("wheelZoom","滚轮缩放");Field("zoomStep","缩放步长");Field("minViewSize","视野下限");Field("maxViewSize","视野上限");}
 if(Section("面板与存档")){Field("showPanel","显示调试栏");Field("panelCollapsed","初始收起");Action("保存当前配置",lab.SaveCurrentConfiguration);EditorGUILayout.HelpBox("运行时保存配置，退出Play后写回；正式场景需单独同步。",MessageType.Info);}
 if(Section("角色状态")){Action("扣半血",lab.HalfHealth);Action("回满血",lab.Heal);Action("充满无双",lab.Charge);}
 serializedObject.ApplyModifiedProperties();}
 static void SaveLoadout(CardLab lab){var path=EditorUtility.SaveFilePanelInProject("保存卡牌组合","新组合","asset","保存当前已获得卡牌与等级");if(string.IsNullOrEmpty(path))return;var data=ScriptableObject.CreateInstance<CardLabLoadout>();var entries=new System.Collections.Generic.List<CardLabLoadout.Entry>();foreach(var card in lab.arena.v06Attack.cards){int level=lab.arena.v06Attack.Level(card.kind);if(level>0)entries.Add(new CardLabLoadout.Entry{card=card.kind,level=level});}data.cards=entries.ToArray();AssetDatabase.CreateAsset(data,path);AssetDatabase.SaveAssets();EditorGUIUtility.PingObject(data);}
 void OnSceneGUI(){var lab=(CardLab)target;var origin=lab.arena?lab.arena.transform.position:Vector3.zero;EditorGUI.BeginChangeCheck();var single=Handles.PositionHandle(origin+(Vector3)lab.singleTargetOffset,Quaternion.identity);if(EditorGUI.EndChangeCheck()){Undo.RecordObject(lab,"移动单桩摆放位置");lab.singleTargetOffset=(Vector2)(single-origin);EditorUtility.SetDirty(lab);}Handles.Label(single,"单桩位置");for(int i=0;i<lab.layoutOffsets.Length;i++){EditorGUI.BeginChangeCheck();var pos=Handles.PositionHandle(origin+(Vector3)lab.layoutOffsets[i],Quaternion.identity);if(EditorGUI.EndChangeCheck()){Undo.RecordObject(lab,"移动木桩布局");lab.layoutOffsets[i]=(Vector2)(pos-origin);EditorUtility.SetDirty(lab);}Handles.Label(pos,"布局木桩 "+i);}}
}
